# Deliverable F: revised manuscript, generated from the analysis outputs only (every number is read from output/).
# Writes output/manuscript/revised_manuscript.md and .docx (pandoc). Citations stay as [ref] placeholders.
source("R/00_setup.R")
TAB <- function(n) fread(file.path(OUT, "tables", paste0(n, ".csv")), encoding = "UTF-8")
R <- fromJSON(RES_FILE)
dir.create(file.path(OUT, "manuscript"), FALSE)
nb <- function(x) format(x, big.mark = ",", trim = TRUE)

t2 <- TAB("Table2_primary_models"); t2a <- TAB("Table2a_rates_by_grade"); t2b <- TAB("Table2b_continuous_hb")
t3 <- TAB("Table3_secondary_outcomes"); t4 <- TAB("Table4_time_updated"); t4b <- TAB("Table4b_landmark")
t5 <- TAB("Table5_sensitivity"); fl <- TAB("Fig1_flow_counts"); s1b <- TAB("S1b_rates_tested_vs_untested")
rep <- TAB("S2a_reproduction_comparison"); t1 <- TAB("Table1_baseline_by_grade"); ph <- TAB("S2b_ph_test_primary")
P <- function(level, measure = "Rate", analysis = "^Primary") t2[analysis %like% analysis & measure %like% get("measure", envir = parent.frame(0)) & level == get("level", envir = parent.frame(0)), estimate]
pr <- function(lv, ms = "Rate") t2[analysis %like% "^Primary" & measure %like% ms & level == lv, estimate]
an <- function(a, lv) t2[analysis == a & level == lv, estimate]
sec <- function(o, lv) t3[outcome == o & level == lv, estimate]
tu <- function(a, lv, o = "Stroke (excl. TIA)") t4[analysis == a & level == lv & outcome == o, estimate]
lm <- function(m, g) t4b[landmark_months == m & group == g, adjusted_RR]
fln <- function(pat) fl[step %like% pat, n][1]
rate <- function(g) t2a[grade %like% g]
xs <- function(lv, a = "Cross-sectional logistic, adjusted") rep[Analysis == a & Outcome %like% "Any stroke" & Level == lv, `Reproduced in R`]
ev <- R$cohort$events
ane <- sum(rate("Mild")$women, rate("Moderate")$women, rate("Severe")$women)
N <- R$primary$N
any_ev <- evalue(as.numeric(sub(" .*", "", pr("Any anemia (Hb <12)"))),
                 as.numeric(sub(".*\\(([0-9.]+).*", "\\1", pr("Any anemia (Hb <12)"))), NA)
sens_any <- range(as.numeric(sub(" .*", "", t5[id %like% "^S" & `Any anemia` != "not estimated", `Any anemia`])))
sens_tr <- range(as.numeric(sub(" .*", "", t5[id %like% "^S", `Per grade (trend)`])))
mod_rng <- range(as.numeric(sub(" .*", "", t5[id %like% "^S", Moderate])))
spl <- function(h) t2b[term == paste0("Hb ", h), estimate]
fu <- quantile(readRDS(file.path(DERIVED, "incident_cohort.rds"))$py, c(.5, .25, .75))
pct_anemic <- 100 * ane / N
untested <- s1b[tested == "No baseline Hb"]; tested <- s1b[tested == "Baseline Hb"]
sel <- R$selection$adj_rr_untested
ind <- function(lv) t1[Characteristic == lv & Level == "yes"]

md <- c()
add <- function(...) md <<- c(md, paste0(...), "")
add("# Anemia at diagnosis of benign uterine disease and subsequent stroke: a retrospective cohort study")
add("Running title: Anemia and incident stroke in benign uterine disease")
add("Authors: [Author names, degrees, affiliations]  ")
add("Corresponding author: [name, address, email]")
add("Keywords: anemia; hemoglobin; ischemic stroke; uterine fibroids; endometriosis; adenomyosis; women; cohort")
add("_Revised draft generated by reanalysis/R/12_manuscript.R from the R outputs. Every number comes from code. [ref] marks citations to be supplied and verified; bracketed text marks information the authors must supply._")

add("## Abstract")
add(sprintf("**Background.** Anemia is common in women with uterine fibroids, adenomyosis and endometriosis, mostly because of heavy menstrual bleeding. Whether anemia identified at diagnosis is associated with later stroke in these women is not known."))
add(sprintf("**Methods.** In a retrospective electronic-health-record cohort at one US academic center, we included women aged 18–60 years with a first diagnosis of benign uterine disease in 2018–2026 who were free of recorded stroke or transient ischemic attack (TIA) at diagnosis and had a laboratory hemoglobin (Hb) in the 3 years before or on the diagnosis date. Anemia was Hb <12 g/dL. The outcome was a first stroke (ischemic, hemorrhagic, cerebral venous thrombosis or unspecified) recorded after diagnosis; TIA was analyzed separately. Rate ratios (RR) were estimated by Poisson regression adjusted for demographic and vascular risk factors, uterine diagnosis, hormonal therapy and conditions that cause anemia. Secondary analyses updated Hb over time and examined exposure lags and testing frequency."))
add(sprintf("**Results.** Of %s women (median follow-up %s years), %s (%.1f%%) were anemic. There were %d incident strokes (%d ischemic). The stroke rate was %s per 1,000 person-years without anemia and %s, %s and %s with mild, moderate and severe anemia. Anemia was associated with a higher stroke rate (adjusted RR %s); estimates by severity were %s (mild), %s (moderate) and %s (severe). Below 13 g/dL, each 1 g/dL lower Hb was associated with an RR of %s. Results were similar for ischemic stroke (RR %s) and across sensitivity analyses (RR %s–%s); TIA was not associated with anemia (RR %s). When Hb was updated over time, the association depended on Hb measured shortly before stroke and on how often women were tested: with a 30-day lag and adjustment for testing frequency the RR for moderate anemia was %s. Stroke rates were similar whether anemia resolved or persisted (RR %s).",
  nb(N), f2(fu[1], 1), nb(ane), pct_anemic, ev$stroke, ev$ischemic,
  sub(" .*", "", rate("No anemia")$rate_per_1000py), sub(" .*", "", rate("Mild")$rate_per_1000py), sub(" .*", "", rate("Moderate")$rate_per_1000py), sub(" .*", "", rate("Severe")$rate_per_1000py),
  pr("Any anemia (Hb <12)"), pr("Mild"), pr("Moderate"), pr("Severe"), t2b[term %like% "lower", estimate],
  sec("Ischemic stroke", "Any anemia (Hb <12)"), f2(sens_any[1]), f2(sens_any[2]), sec("TIA", "Any anemia (Hb <12)"),
  tu("TU: 30-day lag + Hb tests in previous year", "Moderate"), lm(12, "Persistent vs resolved")))
add("**Conclusions.** In women with benign uterine disease, anemia at diagnosis was associated with a modestly higher subsequent rate of recorded stroke, mainly ischemic stroke, without a clear gradient by severity. The pattern of findings suggests that anemia marks underlying illness, health-care contact and vascular risk rather than establishing an independent effect. Whether correcting anemia changes stroke risk cannot be addressed by these data.")

add("## Introduction")
add("Stroke in women under 60 is uncommon but causes substantial disability, and a sizeable share of events in young adults are not explained by conventional vascular risk factors [ref]. Anemia has been associated with ischemic stroke in population cohorts and case–control studies [ref]. Proposed explanations include reduced oxygen delivery, a hyperdynamic circulation, reactive thrombocytosis and a hypercoagulable state, but anemia is also a common marker of chronic illness [ref].")
add("Women with benign uterine disease (fibroids, adenomyosis and endometriosis) are a large group with a high burden of anemia, most of it attributed to heavy menstrual bleeding [ref]. Hemoglobin is routinely measured when these conditions are diagnosed. Whether anemia at that point is associated with later stroke has not been examined. Earlier analyses of this cohort compared anemia with stroke recorded at any time; because half of those strokes preceded the gynecologic diagnosis and hemoglobin was often measured after the stroke, they could not establish the order of events. We therefore studied anemia measured before or at diagnosis and strokes recorded afterwards.")

add("## Methods")
add("### Design, setting and participants")
add(sprintf("This retrospective cohort study used electronic health records from a US academic medical center [site; IRB approval and waiver of consent to be added]. The index date was each woman's first recorded diagnosis of uterine fibroids, adenomyosis or endometriosis (ICD-10 codes) in an extract covering 2018–2026. Of %s women, we excluded %s with active malignancy within 6 months of the index date, %s aged over 60, %s aged under 18 and %s whose age could not be derived. Of the %s eligible women, we further excluded %s with a stroke or TIA recorded before or at the index encounter and %s whose stroke could not be dated, %s with no laboratory Hb in the 3 years before or on the index date, and %s with no follow-up after the index date (Figure 1). The study is reported according to STROBE. A statistical analysis plan was written and time-stamped before analysis.",
  nb(fln("^Records")), nb(fln("malignancy")), nb(fln("age >60")), nb(fln("age <18")), nb(fln("not derivable")), nb(fln("^Eligible")),
  nb(fln("before index or at")), nb(fln("unknown timing")), nb(fln("no laboratory CBC")), nb(fln("no follow-up"))))
add("### Exposure")
add("Hemoglobin was taken from the laboratory results extract. We included whole-blood complete-blood-count Hb only, excluding point-of-care, blood-gas, urine and other Hb tests, implausible values (outside 3–20 g/dL) and sentinel codes; several results on one day were summarized by their median. The exposure was the most recent Hb in the 3 years up to and including the index date, so that it always preceded follow-up. Anemia was defined by the World Health Organization threshold for non-pregnant women (Hb <12 g/dL) and graded as mild (10.0–11.9 g/dL), moderate (8.0–9.9) or severe (<8.0); these bands follow the Common Terminology Criteria for Adverse Events and differ from the WHO severity bands. Hb was also analyzed as a continuous variable.")
add("### Outcomes")
add("Stroke and TIA were identified from diagnosis and problem-list codes, supplemented by brain-imaging reports, with the date of the earliest qualifying code. The primary outcome was a first stroke (ischemic, intracerebral or subarachnoid hemorrhage, cerebral venous thrombosis, or unspecified) dated after the index date. Each woman's stroke type was the most specific type recorded. Secondary outcomes were ischemic stroke, TIA, stroke or TIA combined, and hemorrhagic subtypes. Follow-up ended at stroke, death, last recorded contact or 25 September 2026.")
add("### Covariates")
add("Covariates were chosen from a causal diagram before analysis: age, race, body mass index (BMI), smoking (never, ever, unknown), hypertension, diabetes, dyslipidemia, coronary artery disease, migraine, hormonal therapy type, uterine diagnosis group, and conditions that cause anemia and are associated with stroke, each recorded on or before the index date (hemoglobinopathy, chronic kidney disease, chronic liver disease, alcohol use disorder, inflammatory bowel disease or HIV, malabsorption, and gastrointestinal bleeding or pregnancy in the preceding year). Heavy uterine bleeding was not adjusted for because it leads to anemia rather than confounding its association with stroke; thrombophilia, atrial fibrillation, heart failure and venous thromboembolism were not adjusted for in the primary model because they were undated and often recorded after a stroke. Both choices were tested in sensitivity analyses.")
add("### Statistical analysis")
add(sprintf("Rate ratios were estimated by Poisson regression with a person-time offset and robust standard errors and confirmed by Cox regression (hazard ratios; proportional hazards assessed with Schoenfeld residuals). BMI was missing for %s%% and was multiply imputed (20 imputations); smoking status unknown was analyzed as a category. Anemia was analyzed as any versus none, by grade, as a per-grade trend, per 1 g/dL below and above 13 g/dL, and as a restricted cubic spline (4 knots; reference 13 g/dL). Cumulative incidence was estimated with death as a competing event. Pre-specified sensitivity analyses addressed early events, exposure timing and definition, outcome misdating, adjustment choices, testing frequency, confounding by anemia-causing illness, competing death and selection into testing (inverse-probability weights). E-values described the strength of unmeasured confounding needed to explain the association. In secondary analyses, Hb was updated at every measurement (carried forward up to 1 year, never effective on its own measurement day, with time without a recent value as a separate category), with 30- and 90-day lags and adjustment for the number of Hb tests in the previous year; a landmark analysis at 12 and 24 months compared anemia that resolved with anemia that persisted. Secondary outcomes are exploratory; Benjamini–Hochberg q-values are reported for their trend tests. Analyses used R %s; code is available at [repository].",
  f2(100 * R$missing_incident$bmi / N, 1), paste(R.version$major, R.version$minor, sep = ".")))

add("## Results")
add("### Participants")
add(sprintf("The cohort comprised %s women (Table 1), followed for %s person-years (median %s years, IQR %s–%s). At baseline %s (%.1f%%) were anemic: %s mild, %s moderate and %s severe. Anemic women more often had fibroids, heavy bleeding, hemoglobinopathy and chronic kidney disease, and less often migraine. Women without a baseline Hb (excluded) had less recorded comorbidity and a lower crude stroke rate (%s vs %s per 1,000 person-years; adjusted RR %s).",
  nb(N), nb(round(R$primary$py)), f2(fu[1], 1), f2(fu[2], 1), f2(fu[3], 1), nb(ane), pct_anemic, nb(rate("Mild")$women), nb(rate("Moderate")$women), nb(rate("Severe")$women),
  untested$rate_per_1000py, tested$rate_per_1000py, fci(sel$est, sel$lo, sel$hi)))
add("### Anemia and incident stroke")
add(sprintf("There were %d incident strokes (%d ischemic, %d intracerebral hemorrhage, %d subarachnoid hemorrhage, %d cerebral venous thrombosis, %d unspecified) and %d TIAs. The stroke rate was %s per 1,000 person-years without anemia and %s, %s and %s with mild, moderate and severe anemia; 5-year cumulative incidence was %s%%, %s%%, %s%% and %s%% (Table 2, Figure S1). After adjustment, anemia was associated with a higher stroke rate (RR %s; hazard ratio from the Cox model similar). By grade, RRs were %s, %s and %s; the per-grade trend was %s. The moderate and severe estimates were based on %d and %d strokes. The association changed little from crude (RR %s) to fully adjusted. The E-value was %s (%s for the confidence limit).",
  ev$stroke, ev$ischemic, ev$ich, ev$sah, ev$cvt, ev$unknown, ev$tia,
  rate("No anemia")$rate_per_1000py, rate("Mild")$rate_per_1000py, rate("Moderate")$rate_per_1000py, rate("Severe")$rate_per_1000py,
  sub(" .*", "", rate("No anemia")$cumulative_incidence_5y_pct), sub(" .*", "", rate("Mild")$cumulative_incidence_5y_pct),
  sub(" .*", "", rate("Moderate")$cumulative_incidence_5y_pct), sub(" .*", "", rate("Severe")$cumulative_incidence_5y_pct),
  pr("Any anemia (Hb <12)"), pr("Mild"), pr("Moderate"), pr("Severe"), pr("Per grade (trend)"),
  rate("Moderate")$strokes, rate("Severe")$strokes, an("Crude", "Any anemia (Hb <12)"), f2(any_ev[1]), f2(any_ev[2])))
add(sprintf("Below 13 g/dL, each 1 g/dL lower Hb was associated with an RR of %s; above 13 g/dL the RR was %s. On the spline, RRs relative to 13 g/dL were %s at 12 g/dL, %s at 10 g/dL and %s at 8 g/dL (overall P = %s; non-linearity P = %s; Figure 2).",
  t2b[term %like% "lower", estimate], t2b[term %like% "higher", estimate], spl(12), spl(10), spl(8),
  t2b[term == "overall association", p], t2b[term == "non-linearity", p]))
add("### Secondary outcomes")
add(sprintf("Anemia was associated with ischemic stroke (RR %s; per grade %s) but not with TIA (RR %s; per grade %s; no TIA occurred in women with moderate or severe anemia). Combining TIA with stroke gave an RR of %s. Hemorrhagic subtypes were too few for reliable estimates (Table 3).",
  sec("Ischemic stroke", "Any anemia (Hb <12)"), sec("Ischemic stroke", "Per grade (trend)"), sec("TIA", "Any anemia (Hb <12)"),
  sec("TIA", "Per grade (trend)"), sec("Stroke or TIA (Codebook stroke_any)", "Any anemia (Hb <12)")))
add("### Sensitivity analyses")
add(sprintf("The RR for any anemia ranged from %s to %s and the per-grade RR from %s to %s across sensitivity analyses (Table 4), including exclusion of strokes in the first 30 days (RR %s), restriction to Hb within 1 year (%s), events with an acute stroke code (%s), adjustment for testing frequency before diagnosis (%s), exclusion of women with anemia-causing conditions (%s) and weighting for selection into testing (per grade %s). The moderate-grade estimate ranged from %s to %s and its confidence interval included 1 in every analysis.",
  f2(sens_any[1]), f2(sens_any[2]), f2(sens_tr[1]), f2(sens_tr[2]),
  t5[id == "S2", `Any anemia`], t5[id == "S3", `Any anemia`], t5[id == "S5", `Any anemia`], t5[id == "S8", `Any anemia`], t5[id == "S9", `Any anemia`],
  t5[id == "S11", `Per grade (trend)`], f2(mod_rng[1]), f2(mod_rng[2])))
add("### Time-updated hemoglobin and persistence of anemia")
add(sprintf("With Hb updated over time (%s women; %s person-years; %d strokes), the RR for moderate anemia was %s without a lag. Person-time without a recent Hb had a lower stroke rate (RR %s), indicating that blood testing and stroke recording occur at the same encounters. With a 30-day lag the RR for moderate anemia was %s, with a 90-day lag %s, and with a 30-day lag plus adjustment for testing frequency %s (per grade %s; Table 5). In the 12-month landmark analysis, stroke rates were similar whether baseline anemia had resolved or persisted (RR persistent vs resolved %s; at 24 months %s).",
  nb(t4$women[1]), nb(round(t4$person_years[1])), t4[outcome == "Stroke (excl. TIA)"]$events[1],
  tu("TU primary: 1-y carry-forward, no lag", "Moderate"), tu("TU primary: 1-y carry-forward, no lag", "No recent Hb"),
  tu("TU: 30-day lag", "Moderate"), tu("TU: 90-day lag", "Moderate"),
  tu("TU: 30-day lag + Hb tests in previous year", "Moderate"), tu("TU: 30-day lag + Hb tests in previous year", "Per grade (trend, measured time)"),
  lm(12, "Persistent vs resolved"), lm(24, "Persistent vs resolved")))
add("### Comparison with the earlier cross-sectional analysis")
add(sprintf("Re-fitting the earlier analysis, which compared anemia with stroke or TIA recorded at any time, reproduced its estimates (odds ratios %s, %s and %s for mild, moderate and severe anemia). That analysis included %s strokes recorded before or at diagnosis and Hb values measured after the stroke, and its larger estimates for moderate and severe anemia were not seen when the order of events was enforced (Supplementary Table S2).",
  xs("Mild"), xs("Moderate"), xs("Severe"), nb(fln("before index or at"))))

add("## Discussion")
add(sprintf("In this cohort of women with benign uterine disease, anemia at diagnosis was associated with a modestly higher rate of subsequent recorded stroke, mainly ischemic stroke. The absolute difference was small (5-year incidence %s%% without and %s–%s%% with anemia). The association was consistent across sensitivity analyses addressing timing, exposure definition, outcome definition, adjustment choices and selection, but there was no clear gradient by severity, and estimates for moderate and severe anemia were imprecise.",
  sub(" .*", "", rate("No anemia")$cumulative_incidence_5y_pct), sub(" .*", "", rate("Mild")$cumulative_incidence_5y_pct), sub(" .*", "", rate("Severe")$cumulative_incidence_5y_pct)))
add("Several findings suggest that anemia acts mainly as a marker. First, when hemoglobin was updated over time, much of the association came from values measured shortly before a recorded stroke and from how often women were tested; time without blood tests also had fewer recorded strokes, so testing and stroke recording happen together. Second, resolution of anemia was not followed by a lower stroke rate than persistence, which would be expected if low oxygen-carrying capacity itself drove risk, although these estimates were imprecise. Third, there was no gradient across grades and no association with TIA. Anemia in these women is often due to bleeding, but it also accompanies chronic kidney, liver, inflammatory and hematologic disease, and women with anemia have more contact with health services, which increases the chance that both anemia and stroke are recorded [ref]. Adjustment for, and exclusion of, recorded anemia-causing conditions did not remove the association, but undiagnosed illness and differences in care-seeking may remain; the E-value indicates that a modest unmeasured confounder could explain the lower confidence limit.")
add("These findings temper earlier analyses of this cohort that reported larger odds ratios for moderate and severe anemia. Those analyses compared anemia with stroke recorded at any time, half of which preceded the gynecologic diagnosis, and often used hemoglobin measured after the stroke; acute illness and hospital care lower hemoglobin [ref], so that design overstates the association with severe anemia.")
add("Clinically, anemia found at gynecologic diagnosis may prompt attention to its cause and to conventional vascular risk factors, as it would in any patient. These data do not support stroke screening based on hemoglobin, and they cannot show whether treating anemia changes stroke risk.")
add("### Strengths and limitations")
add(sprintf("Strengths include a large cohort, a pre-specified analysis plan, laboratory values re-derived from raw dated results, dated comorbidities, a design in which exposure preceded the outcome, and extensive sensitivity analyses. Limitations are important. The study was conducted at a single center. Strokes were identified from codes and imaging reports and dated by the earliest code, not by chart review; %d incident events rested on sequela codes or imaging alone (restricting to acute-coded events did not change the results). Women without a baseline Hb (%.0f%% of those free of stroke) differed from tested women, and their outcomes were also less completely recorded. Smoking status was unknown for %s%% of women. Several conditions (thrombophilia, atrial fibrillation, heart failure, venous thromboembolism, migraine) and hormonal therapy were not reliably dated. Admission records, transfusions and outpatient iron prescriptions were not available. Severe anemia and hemorrhagic stroke were uncommon. The index date is the first diagnosis within records beginning in 2018.",
  R$outcome_audit$after_index_no_acute_code, 100 * untested$women / (untested$women + tested$women),
  f2(100 * R$missing_incident$smoking3 / N, 1)))
add("### Conclusions")
add("Anemia at diagnosis of benign uterine disease was associated with a modestly higher subsequent rate of recorded stroke, mainly ischemic stroke, without a clear severity gradient. The pattern suggests that anemia is a marker of underlying illness and health-care contact. Prospective studies with verified outcomes would be needed to determine whether anemia or its causes contribute to stroke risk in this population.")
add("Acknowledgements, funding, disclosures: [to be completed]. Data availability: [statement]; analysis code: [repository].")

# ---- tables -------------------------------------------------------------------------------------------------
mdtab <- function(d) {
  d <- as.data.table(d); d[] <- lapply(d, function(x) { x <- as.character(x); x[is.na(x)] <- ""; gsub("\\|", "/", x) })
  c(paste0("| ", paste(names(d), collapse = " | "), " |"), paste0("|", paste(rep("---", ncol(d)), collapse = "|"), "|"),
    apply(d, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |")))
}
keep1 <- c("Age at index, years", "Race", "BMI, kg/m²", "Smoking", "Hypertension", "Diabetes", "Dyslipidemia",
           "Coronary artery disease (before index)", "Migraine (any)", "Uterine diagnosis group", "Heavy/abnormal uterine bleeding",
           "Hemoglobinopathy (any date)", "CKD (before index)", "Chronic liver disease (before index)", "Any anemia-causing condition",
           "Baseline Hb, g/dL", "Follow-up, years", "Incident stroke (excl. TIA)", "Incident stroke or TIA", "Death without stroke")
add("**Table 1. Baseline characteristics by anemia grade (incident-stroke cohort)**")
md <- c(md, mdtab(t1[Characteristic %in% keep1]), "", "_n (%) of known values or median (IQR); P from χ² or Kruskal–Wallis tests. Full table in the supplement._", "")
add("**Table 2. Baseline anemia and incident stroke (excluding TIA)**")
tt <- merge(t2a[, .(grade, women, strokes, person_years, rate_per_1000py, cumulative_incidence_5y_pct)],
            data.table(grade = t2a$grade, rr = c("1.00 (reference)", pr("Mild"), pr("Moderate"), pr("Severe"))[match(sub(" .*", "", t2a$grade), c("No", "Mild", "Moderate", "Severe"))],
                       hr = c("1.00 (reference)", pr("Mild", "Hazard"), pr("Moderate", "Hazard"), pr("Severe", "Hazard"))[match(sub(" .*", "", t2a$grade), c("No", "Mild", "Moderate", "Severe"))]), by = "grade", sort = FALSE)
tt <- rbind(tt, data.table(grade = "Any anemia (Hb <12)", rr = pr("Any anemia (Hb <12)")), data.table(grade = "Per grade (trend)", rr = pr("Per grade (trend)"), hr = pr("Per grade (trend)", "Hazard")), fill = TRUE)
setnames(tt, c("Baseline Hb", "Women", "Strokes", "Person-years", "Rate /1,000 PY (95% CI)", "5-y cumulative incidence, % (95% CI)", "Adjusted rate ratio (95% CI)", "Adjusted hazard ratio (95% CI)"))
md <- c(md, mdtab(tt), "", sprintf("_Poisson (robust SE) and Cox models adjusted for age, race, BMI, smoking, hypertension, diabetes, dyslipidemia, CAD, migraine, hormonal therapy, uterine diagnosis group and pre-index anemia-causing conditions; 20 imputations for BMI; n = %s. Cumulative incidence by Aalen–Johansen with death as competing event. Per 1 g/dL lower Hb below 13 g/dL: RR %s._", nb(N), t2b[term %like% "lower", estimate]), "")
add("**Table 3. Secondary incident outcomes (exploratory)**")
md <- c(md, mdtab(t3[, .(Outcome = outcome, Level = level, `Rate ratio (95% CI)` = estimate, Events = events, Adjustment = adjustment, q = q_BH, Note = note)]), "")
add("**Table 4. Sensitivity analyses (rate ratios unless stated)**")
md <- c(md, mdtab(t5[, .(ID = id, Analysis = analysis, `Bias addressed` = bias_addressed, N, Events = events, Mild, Moderate, Severe, `Per grade` = `Per grade (trend)`, `Any anemia`)]), "")
add("**Table 5. Time-updated hemoglobin and stroke (excluding TIA)**")
md <- c(md, mdtab(dcast(t4[outcome == "Stroke (excl. TIA)", .(Model = analysis, level, estimate)], Model ~ level, value.var = "estimate")), "",
        "_Most recent laboratory Hb, carried forward up to 1 year (3 years in the last row); never effective on its measurement day; Poisson with SE clustered by woman, full adjustment, 20 imputations._", "")
add("## Figures")
for (f in list(c("Figure1_flow.png", "Figure 1. Cohort flow."),
               c("Figure2_spline.png", "Figure 2. Baseline hemoglobin and incident stroke: adjusted rate ratio relative to 13 g/dL (restricted cubic spline), with the distribution of Hb."),
               c("Figure3_forest.png", "Figure 3. Estimates by design and effect measure: (A) primary incident analysis, (B) secondary outcomes, (C) time-updated Hb without and with a 30-day lag, (D) the earlier cross-sectional odds ratios for comparison."),
               c("FigureS1_cumulative_incidence.png", "Figure S1. Cumulative incidence of stroke by baseline anemia grade (death as competing event).")))
  add(sprintf("![%s](../figures/%s)", f[2], f[1]))
writeLines(md, file.path(OUT, "manuscript", "revised_manuscript.md"))
owd <- setwd(file.path(OUT, "manuscript"))
st <- system2("pandoc", c("revised_manuscript.md", "-o", "revised_manuscript.docx", "--resource-path=.:../figures"))
setwd(owd)
log_msg("Manuscript", sprintf("revised manuscript written (%d words in md; pandoc status %d)", sum(lengths(strsplit(md, "\\s+"))), st))
